import java.io.*;

class Conexion implements AutoCloseable {
    private String nombre;

    public Conexion(String nombre) {
        this.nombre = nombre;
        System.out.println("Opening connection: " + nombre);
    }

    @Override
    public void close() throws Exception {
        System.out.println("Closing connection: " + nombre);
    }
}

public class GestorConexiones {
    public static Conexion abrirConexion(String nombre) throws IOException {
        if (nombre.contains("Respaldo")) {
            throw new IOException("Could not connect to: " + nombre);
        }
        return new Conexion(nombre);
    }

    public static void main(String[] args) {
        try (Conexion c1 = abrirConexion("BD-Principal");
             Conexion c2 = abrirConexion("BD-Respaldo")) {
            System.out.println("Using connections...");
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}
